interface.signature:
Request:
  Query: { version?: '3.0' | '3.1', environment?: string }
  Headers: { Authorization: 'Bearer {api_key}' }
  Body: OpenAPI spec JSON object

Response 200 (sync processed):
  { api_id, version_id, status: 'processed', endpoints_count, message }

Response 202 (async queued):
  { api_id, version_id, job_id, status: 'queued', message }

Response 400 (validation error):
  { error: { code: 'INVALID_SPEC', message, details: { errors } } }

Response 401 (unauthorized):
  { error: { code: 'UNAUTHORIZED', message } }

Response 403 (forbidden):
  { error: { code: 'FORBIDDEN', message } }

interface SpecMetadata {
  name: string
  version: string
  team?: string
  owner?: string
}

class SpecMetadataService {
  extractMetadata(spec: object): SpecMetadata
  private sanitizeApiName(title: string): string
}

interface StorageResult {
  apiId: string
  versionId: string
  endpointsCount: number
  isNewApi: boolean
}

class SpecStorageService {
  async store(spec: object, metadata: SpecMetadata, environment: string, uploadedBy: string): Promise<StorageResult>
  countEndpoints(spec: object): number
}

declare module 'fastify' {
  interface FastifyRequest {
    apiKeyId: string | null  // Already defined in auth.ts
  }
}

// From Story 2.2
fastify.openAPIValidationService.validate(spec: unknown): Promise<ValidationResult>

interface ValidationResult {
  valid: boolean
  errors?: ValidationError[]
  dereferenced?: object  // Bundled spec ready for storage
}

// Create API record
await db.api.create({
  data: { name, team?, owner?, createdAt, updatedAt }
})

// Find existing API
await db.api.findFirst({
  where: { name: { equals: name, mode: 'insensitive' } }
})

// Create version record
await db.apiVersion.create({
  data: { apiId, version, environment, specJson, uploadedAt, uploadedBy? }
})
